INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('78ece41c-115b-42c7-b9ab-f4e888bd44c3', 'b2b2b2b2-3030-4000-8000-000000000002', 27, 'Dia 27 — Conexão', 'Semana 4: Integrar', '{"pch": "Levai as cargas uns dos outros\u2026 Cura n\u00e3o acontece no isolamento.", "verse": "Gl 6,2", "lectio": "Leia Gl 6,1-5. Comunidade na restaura\u00e7\u00e3o.", "practice": "Ligue para algu\u00e9m. Diga: preciso de voc\u00ea.", "question": "Quem voc\u00ea precisa ao seu lado neste momento?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;